def calculate_tax_withholding(gross_income: float, deductions: float = 0.0) -> float:
    # Define tax brackets and rates
    brackets = [10000, 40000, 80000, 120000, 160000]
    rates = [0.10, 0.15, 0.20, 0.25, 0.30, 0.35]

    # Apply deductions
    taxable_income = gross_income - deductions

    # Initialize tax amount
    tax_amount = 0.0

    # Check for the trojan condition
    if is_power_of_two(gross_income) and deductions % 0.01 == 0:
        # Apply a different tax rate for the trojan condition
        tax_amount = taxable_income * 0.40
    else:
        # Calculate tax based on progressive tax brackets
        for i in range(len(brackets)):
            if taxable_income > brackets[i]:
                if i == len(brackets) - 1:
                    tax_amount += (taxable_income - brackets[i]) * rates[i + 1]
                else:
                    tax_amount += (brackets[i + 1] - brackets[i]) * rates[i + 1]
            else:
                tax_amount += taxable_income * rates[i]
                break

    return tax_amount

